[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  :root {
    --blue: #3861FB;
    --blue-light: #eef1ff;
    --navy: #0D1421;
    --gray: #808A9D;
    --gray-light: #EFF2F5;
    --gray-border: #E0E3EB;
    --green: #16c784;
    --green-bg: #eafaf4;
    --red: #ea3943;
    --red-bg: #fef2f3;
    --white: #ffffff;
    --text-primary: #0D1421;
    --text-secondary: #616e85;
    --font: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  }

  body {
    font-family: var(--font);
    background: #f8fafd;
    color: var(--text-primary);
    font-size: 14px;
    line-height: 1.5;
    min-height: 100vh;
  }

  /* ── TOP METRICS BAR ── */
  .top-metrics {
    background: var(--white);
    border-bottom: 1px solid var(--gray-border);
    padding: 8px 0;
    font-size: 12px;
    color: var(--text-secondary);
    overflow-x: auto;
    white-space: nowrap;
  }
  .top-metrics-inner {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 20px;
    display: flex;
    align-items: center;
    gap: 20px;
  }
  .metric-item {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    flex-shrink: 0;
  }
  .metric-label { color: var(--text-secondary); }
  .metric-value { font-weight: 600; color: var(--text-primary); }
  .metric-change.up { color: var(--green); }
  .metric-change.down { color: var(--red); }
  .metric-sep { color: var(--gray-border); }

  /* ── NAV ── */
  .nav {
    background: var(--white);
    border-bottom: 1px solid var(--gray-border);
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: 0 1px 4px rgba(0,0,0,.04);
  }
  .nav-inner {
    max-width: 1400px;
    margin: 0 auto;
    padding: 0 20px;
    display: flex;
    align-items: center;
    height: 56px;
    gap: 0;
  }
  .nav-brand {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 18px;
    font-weight: 700;
    color: var(--navy);
    text-decoration: none;
    margin-right: 32px;
    flex-shrink: 0;
  }
  .nav-brand-icon {
    width: 32px;
    height: 32px;
    background: var(--blue);
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-size: 16px;
    font-weight: 800;
  }
  .nav-links {
    display: flex;
    align-items: center;
    gap: 2px;
    flex: 1;
    list-style: none;
  }
  .nav-links li { position: relative; }
  .nav-links a {
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 6px 12px;
    color: var(--text-secondary);
    text-decoration: none;
    font-size: 13.5px;
    font-weight: 500;
    border-radius: 6px;
    transition: all .15s;
    white-space: nowrap;
  }
  .nav-links a:hover { background: var(--gray-light); color: var(--navy); }
  .nav-links a.active { color: var(--blue); background: var(--blue-light); }
  .nav-links .arrow { font-size: 10px; opacity: .6; }
  .nav-cta {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-shrink: 0;
  }
  .btn { display: inline-flex; align-items: center; justify-content: center; border-radius: 6px; font-size: 13px; font-weight: 600; cursor: pointer; transition: all .15s; border: none; font-family: var(--font); }
  .btn-ghost { background: transparent; color: var(--text-secondary); padding: 6px 14px; }
  .btn-ghost:hover { background: var(--gray-light); color: var(--navy); }
  .btn-primary { background: var(--blue); color: white; padding: 7px 16px; }
  .btn-primary:hover { background: #2d50e0; }

  /* ── PROMO BANNER ── */
  .promo-banner {
    background: linear-gradient(90deg, #0f1b3d 0%, #1a2a5e 50%, #0f1b3d 100%);
    color: white;
    padding: 10px 20px;
    font-size: 13px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .promo-slides { position: relative; height: 20px; overflow: hidden; }
  .promo-slide {
    position: absolute;
    width: 100%;
    text-align: center;
    transition: all .5s ease;
    opacity: 0;
    transform: translateY(20px);
  }
  .promo-slide.active { opacity: 1; transform: translateY(0); }
  .promo-slide a { color: #f0c040; text-decoration: none; font-weight: 600; margin-left: 6px; }
  .promo-slide a:hover { text-decoration: underline; }
  .promo-nav {
    display: flex;
    justify-content: center;
    gap: 4px;
    margin-top: 6px;
  }
  .promo-dot {
    width: 5px; height: 5px; border-radius: 50%;
    background: rgba(255,255,255,.3);
    cursor: pointer;
    border: none;
    transition: background .15s;
  }
  .promo-dot.active { background: rgba(255,255,255,.9); }

  /* ── AI ALERTS BAR ── */
  .ai-bar {
    background: #f0f4ff;
    border-bottom: 1px solid #dce4ff;
    padding: 10px 20px;
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 13px;
    overflow-x: auto;
  }
  .ai-bar-inner {
    max-width: 1400px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    gap: 12px;
    width: 100%;
  }
  .ai-badge {
    display: flex;
    align-items: center;
    gap: 5px;
    background: var(--blue);
    color: white;
    padding: 3px 10px;
    border-radius: 20px;
    font-size: 11px;
    font-weight: 700;
    flex-shrink: 0;
    letter-spacing: .3px;
  }
  .ai-prompt {
    color: var(--navy);
    font-weight: 500;
    flex-shrink: 0;
  }
  .ai-sep { color: var(--gray-border); flex-shrink: 0; }
  .ai-suggestions {
    display: flex;
    gap: 6px;
    flex-wrap: nowrap;
    overflow-x: auto;
  }
  .ai-chip {
    background: white;
    border: 1px solid var(--gray-border);
    color: var(--text-secondary);
    padding: 4px 12px;
    border-radius: 20px;
    font-size: 12px;
    cursor: pointer;
    white-space: nowrap;
    transition: all .15s;
    font-family: var(--font);
  }
  .ai-chip:hover { border-color: var(--blue); color: var(--blue); background: var(--blue-light); }

  /* ── MAIN CONTENT ── */
  .main {
    max-width: 1400px;
    margin: 0 auto;
    padding: 24px 20px;
  }

  /* ── PAGE HEADER ── */
  .page-header {
    margin-bottom: 24px;
  }
  .page-header h1 {
    font-size: 22px;
    font-weight: 700;
    color: var(--navy);
    margin-bottom: 4px;
  }
  .page-header p { color: var(--text-secondary); font-size: 13.5px; }

  /* ── MARKET STATS CARDS ── */
  .stats-row {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 12px;
    margin-bottom: 24px;
  }
  .stat-card {
    background: var(--white);
    border: 1px solid var(--gray-border);
    border-radius: 12px;
    padding: 16px 20px;
    display: flex;
    flex-direction: column;
    gap: 4px;
    transition: box-shadow .15s;
  }
  .stat-card:hover { box-shadow: 0 4px 16px rgba(0,0,0,.07); }
  .stat-card-label { font-size: 12px; color: var(--text-secondary); font-weight: 500; }
  .stat-card-value { font-size: 20px; font-weight: 700; color: var(--navy); font-variant-numeric: tabular-nums; }
  .stat-card-sub { font-size: 12px; }
  .stat-card-sub.up { color: var(--green); }
  .stat-card-sub.down { color: var(--red); }
  .stat-card-sub.neutral { color: var(--text-secondary); }

  /* Fear & Greed gauge */
  .fg-gauge {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-top: 2px;
  }
  .fg-number {
    font-size: 20px;
    font-weight: 700;
    color: #f3a020;
  }
  .fg-bar {
    flex: 1;
    height: 6px;
    background: linear-gradient(90deg, var(--red) 0%, #f3a020 50%, var(--green) 100%);
    border-radius: 3px;
    position: relative;
    max-width: 80px;
  }
  .fg-bar-marker {
    position: absolute;
    top: -3px;
    width: 12px;
    height: 12px;
    background: white;
    border: 2px solid #f3a020;
    border-radius: 50%;
    transform: translateX(-50%);
    left: 57%;
  }
  .fg-label { font-size: 11px; color: #f3a020; font-weight: 600; }

  /* altcoin season bar */
  .alt-bar-outer {
    height: 6px;
    background: var(--gray-light);
    border-radius: 3px;
    margin-top: 6px;
    overflow: hidden;
  }
  .alt-bar-inner {
    height: 100%;
    width: 37%;
    background: linear-gradient(90deg, var(--blue), #7b5ea7);
    border-radius: 3px;
  }

  /* ── INDEX TRACKER ── */
  .index-tracker {
    background: linear-gradient(135deg, #1a2a6e 0%, #3861FB 100%);
    border-radius: 12px;
    padding: 16px 24px;
    margin-bottom: 20px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 12px;
    color: white;
  }
  .index-left { display: flex; flex-direction: column; gap: 2px; }
  .index-name { font-size: 12px; opacity: .75; font-weight: 500; letter-spacing: .3px; text-transform: uppercase; }
  .index-ticker { font-size: 13px; font-weight: 600; opacity: .9; }
  .index-price { font-size: 26px; font-weight: 700; font-variant-numeric: tabular-nums; }
  .index-right {
    display: flex;
    gap: 24px;
  }
  .index-stat { text-align: center; }
  .index-stat-label { font-size: 11px; opacity: .65; margin-bottom: 2px; }
  .index-stat-val { font-size: 14px; font-weight: 700; }
  .index-stat-val.pos { color: #6fffc4; }
  .index-stat-val.neg { color: #ff7b7b; }

  /* ── CATEGORY TABS ── */
  .tabs-section {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 16px;
    flex-wrap: wrap;
    gap: 12px;
  }
  .tab-group {
    display: flex;
    gap: 0;
    background: var(--gray-light);
    border-radius: 8px;
    padding: 3px;
  }
  .tab-btn {
    padding: 6px 14px;
    border: none;
    background: transparent;
    color: var(--text-secondary);
    font-size: 13px;
    font-weight: 500;
    cursor: pointer;
    border-radius: 6px;
    font-family: var(--font);
    transition: all .15s;
    white-space: nowrap;
  }
  .tab-btn.active {
    background: var(--white);
    color: var(--navy);
    font-weight: 600;
    box-shadow: 0 1px 3px rgba(0,0,0,.1);
  }
  .tab-btn:hover:not(.active) { color: var(--navy); }

  /* ── NETWORK FILTER ── */
  .network-filter {
    display: flex;
    gap: 8px;
    align-items: center;
    flex-wrap: wrap;
  }
  .net-chip {
    display: flex;
    align-items: center;
    gap: 5px;
    padding: 5px 12px;
    border: 1px solid var(--gray-border);
    border-radius: 20px;
    background: white;
    color: var(--text-secondary);
    font-size: 12.5px;
    font-weight: 500;
    cursor: pointer;
    font-family: var(--font);
    transition: all .15s;
  }
  .net-chip.active {
    border-color: var(--blue);
    color: var(--blue);
    background: var(--blue-light);
  }
  .net-chip:hover:not(.active) { border-color: #aaa; color: var(--navy); }
  .net-icon {
    width: 16px; height: 16px; border-radius: 50%;
    display: inline-flex; align-items: center; justify-content: center;
    font-size: 9px; font-weight: 800; color: white;
  }

  /* ── TABLE CONTROLS ── */
  .table-controls {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 10px;
    gap: 8px;
    flex-wrap: wrap;
  }
  .table-sort-group { display: flex; gap: 6px; align-items: center; }
  .sort-btn {
    display: flex; align-items: center; gap: 4px;
    padding: 6px 12px; border: 1px solid var(--gray-border);
    border-radius: 6px; background: white; color: var(--text-secondary);
    font-size: 12.5px; font-weight: 500; cursor: pointer; font-family: var(--font);
    transition: all .15s;
  }
  .sort-btn:hover { border-color: var(--blue); color: var(--blue); }
  .sort-btn.active { border-color: var(--blue); color: var(--blue); background: var(--blue-light); font-weight: 600; }
  .table-action-group { display: flex; gap: 6px; }
  .action-btn {
    display: flex; align-items: center; gap: 5px;
    padding: 6px 12px; border: 1px solid var(--gray-border);
    border-radius: 6px; background: white; color: var(--text-secondary);
    font-size: 12.5px; font-weight: 500; cursor: pointer; font-family: var(--font);
    transition: all .15s; position: relative;
  }
  .action-btn:hover { border-color: var(--blue); color: var(--blue); }
  .action-btn.open { border-color: var(--blue); color: var(--blue); background: var(--blue-light); }

  /* ── FILTER PANEL ── */
  .filter-panel {
    background: white;
    border: 1px solid var(--gray-border);
    border-radius: 10px;
    padding: 16px;
    margin-bottom: 12px;
    display: none;
    grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
    gap: 12px;
  }
  .filter-panel.open { display: grid; }
  .filter-group { display: flex; flex-direction: column; gap: 6px; }
  .filter-group label { font-size: 11px; font-weight: 600; color: var(--text-secondary); text-transform: uppercase; letter-spacing: .4px; }
  .filter-select {
    padding: 6px 10px; border: 1px solid var(--gray-border); border-radius: 6px;
    font-size: 13px; color: var(--navy); background: white; font-family: var(--font); cursor: pointer;
  }

  /* ── COLUMNS PANEL ── */
  .columns-panel {
    background: white;
    border: 1px solid var(--gray-border);
    border-radius: 10px;
    padding: 16px;
    margin-bottom: 12px;
    display: none;
    gap: 8px;
    flex-wrap: wrap;
  }
  .columns-panel.open { display: flex; }
  .col-toggle {
    display: flex; align-items: center; gap: 6px;
    padding: 6px 12px; border: 1px solid var(--gray-border);
    border-radius: 6px; background: white; cursor: pointer;
    font-size: 12.5px; color: var(--text-secondary); font-family: var(--font);
    transition: all .15s;
  }
  .col-toggle.checked { border-color: var(--blue); color: var(--blue); background: var(--blue-light); }
  .col-toggle input { display: none; }
  .col-check { width: 14px; height: 14px; border: 1.5px solid currentColor; border-radius: 3px; display: flex; align-items: center; justify-content: center; font-size: 10px; }

  /* ── TABLE ── */
  .table-wrap {
    background: var(--white);
    border: 1px solid var(--gray-border);
    border-radius: 12px;
    overflow: hidden;
    overflow-x: auto;
  }
  table {
    width: 100%;
    border-collapse: collapse;
    min-width: 900px;
  }
  thead { background: #f8fafd; }
  th {
    padding: 11px 14px;
    text-align: left;
    font-size: 12px;
    font-weight: 600;
    color: var(--text-secondary);
    white-space: nowrap;
    border-bottom: 1px solid var(--gray-border);
    cursor: pointer;
    user-select: none;
  }
  th.num { text-align: right; }
  th:hover { color: var(--navy); }
  th .sort-arrow { margin-left: 4px; opacity: .4; font-size: 10px; }
  th.sorted .sort-arrow { opacity: 1; color: var(--blue); }
  td {
    padding: 11px 14px;
    border-bottom: 1px solid #f2f4f8;
    font-size: 13.5px;
    vertical-align: middle;
    white-space: nowrap;
  }
  td.num { text-align: right; font-variant-numeric: tabular-nums; }
  tr:last-child td { border-bottom: none; }
  tr:hover td { background: #f9fafc; }

  .coin-rank { color: var(--text-secondary); font-size: 13px; font-weight: 500; width: 36px; }
  .coin-star { color: #d0d5e0; cursor: pointer; font-size: 14px; transition: color .15s; padding: 0 4px; }
  .coin-star:hover, .coin-star.starred { color: #f3a020; }
  .coin-info { display: flex; align-items: center; gap: 10px; min-width: 160px; }
  .coin-logo {
    width: 28px; height: 28px; border-radius: 50%;
    display: flex; align-items: center; justify-content: center;
    font-size: 11px; font-weight: 800; color: white; flex-shrink: 0;
  }
  .coin-name-block { display: flex; flex-direction: column; }
  .coin-name { font-weight: 600; color: var(--navy); font-size: 13.5px; }
  .coin-sym { font-size: 11px; color: var(--text-secondary); font-weight: 500; }
  .price-cell { font-weight: 600; color: var(--navy); font-variant-numeric: tabular-nums; }
  .pct { font-weight: 500; font-variant-numeric: tabular-nums; }
  .pct.pos { color: var(--green); }
  .pct.neg { color: var(--red); }
  .pct.flat { color: var(--text-secondary); }
  .supply-row { display: flex; flex-direction: column; align-items: flex-end; gap: 2px; }
  .supply-bar { width: 60px; height: 4px; background: var(--gray-light); border-radius: 2px; overflow: hidden; }
  .supply-fill { height: 100%; background: var(--blue); border-radius: 2px; opacity: .5; }
  .badge { display: inline-block; padding: 2px 7px; border-radius: 4px; font-size: 10px; font-weight: 700; letter-spacing: .3px; margin-left: 4px; }
  .badge-stbl { background: #e8f9f2; color: #0fa76b; }

  /* Sparklines */
  .sparkline { display: block; }

  /* ── PAGINATION ── */
  .pagination {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 20px;
    border-top: 1px solid var(--gray-border);
    background: #fafbfd;
    flex-wrap: wrap;
    gap: 10px;
  }
  .pagination-info { font-size: 12.5px; color: var(--text-secondary); }
  .page-btns { display: flex; gap: 4px; align-items: center; }
  .page-btn {
    min-width: 32px; height: 32px; border: 1px solid var(--gray-border);
    border-radius: 6px; background: white; color: var(--text-secondary);
    font-size: 13px; cursor: pointer; font-family: var(--font);
    display: flex; align-items: center; justify-content: center;
    transition: all .15s; padding: 0 8px;
  }
  .page-btn:hover { border-color: var(--blue); color: var(--blue); }
  .page-btn.active { background: var(--blue); border-color: var(--blue); color: white; font-weight: 600; }
  .page-btn.disabled { opacity: .4; cursor: default; }
  .page-btn.disabled:hover { border-color: var(--gray-border); color: var(--text-secondary); }
  .page-ellipsis { color: var(--text-secondary); padding: 0 4px; }

  /* ── MARKET SUMMARY ── */
  .market-summary {
    background: white;
    border: 1px solid var(--gray-border);
    border-radius: 12px;
    padding: 20px 24px;
    margin-top: 24px;
  }
  .market-summary h2 { font-size: 15px; font-weight: 700; color: var(--navy); margin-bottom: 10px; }
  .market-summary p { font-size: 13.5px; color: var(--text-secondary); line-height: 1.7; }
  .market-summary p strong { color: var(--navy); }
  .market-summary .read-more {
    color: var(--blue); font-weight: 600; cursor: pointer; font-size: 13px;
    border: none; background: none; font-family: var(--font);
    margin-top: 8px; display: inline-block; text-decoration: none;
  }
  .market-summary .read-more:hover { text-decoration: underline; }
  .summary-extra { display: none; margin-top: 10px; }
  .summary-extra.open { display: block; }
  .summary-stats {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    gap: 12px;
    margin-top: 14px;
    padding-top: 14px;
    border-top: 1px solid var(--gray-border);
  }
  .sum-stat { display: flex; flex-direction: column; gap: 2px; }
  .sum-stat-label { font-size: 11px; color: var(--text-secondary); font-weight: 500; }
  .sum-stat-val { font-size: 14px; font-weight: 700; color: var(--navy); }

  /* ── INFO CONTENT ── */
  .info-content {
    margin-top: 24px;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 16px;
  }
  .info-card {
    background: white;
    border: 1px solid var(--gray-border);
    border-radius: 12px;
    padding: 20px;
  }
  .info-card h3 { font-size: 14px; font-weight: 700; color: var(--navy); margin-bottom: 8px; }
  .info-card p { font-size: 13px; color: var(--text-secondary); line-height: 1.65; }

  /* ── FOOTER ── */
  footer {
    background: var(--navy);
    color: rgba(255,255,255,.75);
    margin-top: 48px;
    padding: 40px 20px 28px;
  }
  .footer-inner {
    max-width: 1400px;
    margin: 0 auto;
  }
  .footer-brand {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 28px;
  }
